CUR[GEN]=UN.map((n,u)=>({n,m:MN[u].map((nm,k)=>{const pre='geo'+OU[u]+(k+1);return {n:nm,q:(GQ[u+'-'+k]||[]).map((q,i)=>Object.assign({id:pre+(q.lv?'x':'b')+String(i+1).padStart(2,'0')},q)).sort((a,b)=>(a.lv?1:0)-(b.lv?1:0))}})}));
const R5=[[],[],[],[],[]];let j=0;
[1,2,0].forEach(u=>MN[u].forEach((_,k)=>(GMK[u+'-'+k]||[]).forEach(q=>{R5[j%5].push({o:(u?u*10:100)+k,q});j++})));
MOCK[GEN]=R5.map((L,r)=>({n:(r+1)+'회',q:L.sort((a,b)=>a.o-b.o).map((x,i)=>Object.assign({id:'geom'+(r+1)+String(i+1).padStart(2,'0'),mk:1,t:'mc'},x.q))}));
